    def rotate_teeth(teeth, i, clockwise):
        new_teeth = teeth[:]
        if clockwise:
            new_teeth[i] = (teeth[i] + 1) % n
        else:
            new_teeth[i] = (teeth[i] - 1 + n) % n
        return new_teeth

